import codecs
class Failure(UnicodeDecodeError):
    def __getattribute__(self, name):
        if name == 'start':
            input()
        return super().__getattribute__(name)
def handler(error):
    raise Failure('ascii', b'\xff', 0, 1, 'original')
codecs.register_error('strict', handler)
b'\xff-a'.decode('punycode')

